/**
 * Contract between the DataTable and the eduardoapatat/laravel-inertia-datatable package.
 *
 * Plain TypeScript, without React, Vue or Inertia dependencies: types of the
 * server response and conversion of the table state to a query string.
 * See docs/contract.md in the package.
 */

export type FilterVariant =
    | 'text'
    | 'number'
    | 'range'
    | 'date'
    | 'date-range'
    | 'boolean'
    | 'select'
    | 'multi-select';

export type FilterOperator =
    | 'iLike'
    | 'notILike'
    | 'eq'
    | 'ne'
    | 'inArray'
    | 'notInArray'
    | 'isEmpty'
    | 'isNotEmpty'
    | 'lt'
    | 'lte'
    | 'gt'
    | 'gte'
    | 'isBetween';

export interface ServerSort {
    id: string;
    desc: boolean;
}

export interface ServerFilter {
    id: string;
    filterId?: string;
    variant: FilterVariant;
    operator: FilterOperator;
    value: string | string[];
}

/**
 * How the currency of `->money()` is shown: the symbol before the number
 * (`$1.234`, by default), the code after it (`1.234 CLP`), both
 * (`$1.234 CLP`) or nothing (`1.234`).
 */
export type CurrencyDisplay = 'symbol' | 'code' | 'both' | 'none';

/**
 * How the cells of a column are displayed; `type` is the type of the column
 * (`Column::number()`, `Column::date()`…). Formats are Intl options, applied on
 * the client with the table locale.
 */
export type ServerColumnDisplay = (
    | {
          type: 'number';
          format?: Intl.NumberFormatOptions;
          /** Unit after plain numbers (`->unit('kg')`). */
          unit?: string;
          /**
           * Where the unit is hidden: in the cells (and the filter label) or
           * next to the filter inputs; shown when missing.
           */
          showUnit?: { cell?: false; filter?: false };
          /**
           * Currency of `->money()` in the cells (and the filter label) and
           * next to the filter inputs; `symbol` when missing.
           */
          currency?: { cell?: CurrencyDisplay; filter?: CurrencyDisplay };
      }
    | {
          type: 'date';
          /** Without it, the date format of the table. */
          format?:
              | 'short'
              | 'medium'
              | 'long'
              | 'datetime'
              | 'relative'
              | Intl.DateTimeFormatOptions;
      }
    | { type: 'text'; limit?: number; link?: 'url' | 'email' }
    | {
          type: 'boolean';
          labels?: { true: string; false: string };
          /** Labels with the project's shadcn Badge. */
          badge?: boolean;
          /** Badge variant of the column (`outline` by default). */
          variant?: string;
          /** Badge variant of `true` and `false`. */
          variants?: { true?: string; false?: string };
      }
    | {
          type: 'option';
          /** Labels with the project's shadcn Badge. */
          badge?: boolean;
          /** Badge variant of the column (`outline` by default). */
          variant?: string;
          /** Badge variant per option value. */
          variants?: Record<string, string>;
      }
) & {
    /**
     * Text of the cells without a value (`->whenEmpty()`); without it, the
     * `empty` message (`—`).
     */
    empty?: string;
};

/** Filter of a column (`->filterInput()`, `->filterSelect()`, `->filterRange()`…). */
export interface ServerColumnFilter {
    variant: FilterVariant;
    placeholder?: string;
    /** The filter also offers the rows without a value (`empty: true`). */
    empty?: true;
}

export interface ServerColumnConfig {
    id: string;
    label: string;
    sortable: boolean;
    hideable: boolean;
    visible: boolean;
    display: ServerColumnDisplay;
    /** Null: the column has no filter. */
    filter: ServerColumnFilter | null;
}

export interface ServerFacetOption {
    /** `null`: the rows without a value, last, with `empty: true`. */
    value: string | null;
    label: string;
    count?: number;
}

export interface ServerRangeFacet {
    min: number | null;
    max: number | null;
}

export interface ServerQueryKeys {
    page: string;
    per_page: string;
    sort: string;
    filter: string;
    search: string;
    columns: string;
}

export interface ServerTableConfig {
    columns: ServerColumnConfig[];
    searchable: boolean;
    /** Locale to format numbers and dates (table, config or app); null uses the browser's. */
    locale?: string | null;
    /** Preset of the date columns without their own format. */
    date_format?: 'short' | 'medium' | 'long' | 'datetime' | 'relative';
    /** UI texts in the app language (lang/vendor/inertia-datatable). */
    messages?: Record<string, string>;
    per_page: number;
    per_page_options: number[];
    default_sorting: ServerSort[];
    query: ServerQueryKeys;
}

export interface ServerTableState {
    pagination: { pageIndex: number; pageSize: number };
    sorting: ServerSort[];
    columnFilters: ServerFilter[];
    globalFilter: string;
    columnVisibility: Record<string, boolean>;
}

/**
 * Package response: the Inertia prop (or the JSON) of a table.
 */
export interface ServerDataTable<TData> {
    data: TData[];
    meta: {
        current_page: number;
        per_page: number;
        last_page: number;
        total: number;
        from: number | null;
        to: number | null;
    };
    state: ServerTableState;
    facets: Record<string, ServerFacetOption[] | ServerRangeFacet>;
    config: ServerTableConfig;
}

/**
 * Table state to put in the URL.
 */
export interface TableQueryState {
    pageIndex: number;
    pageSize: number;
    sorting: ServerSort[];
    filters: ServerFilter[];
    globalFilter: string;
    columnVisibility: Record<string, boolean>;
}

export const FILTER_OPERATOR_URL_NAMES = {
    iLike: 'ilike',
    notILike: 'not.ilike',
    eq: 'eq',
    ne: 'neq',
    inArray: 'in',
    notInArray: 'not.in',
    isEmpty: 'is.empty',
    isNotEmpty: 'not.is.empty',
    lt: 'lt',
    lte: 'lte',
    gt: 'gt',
    gte: 'gte',
    isBetween: 'between',
} as const satisfies Record<FilterOperator, string>;

/**
 * Operator of each variant that the URL leaves out (`filter[name]=ana` is
 * `ilike`): the one of the plain value a filter component writes.
 */
export const IMPLICIT_OPERATORS: Record<FilterVariant, FilterOperator> = {
    text: 'iLike',
    number: 'eq',
    range: 'isBetween',
    date: 'eq',
    'date-range': 'isBetween',
    boolean: 'eq',
    select: 'inArray',
    'multi-select': 'inArray',
};

const LIST_OPERATORS = new Set<FilterOperator>([
    'inArray',
    'notInArray',
    'isBetween',
]);

const VALUELESS_OPERATORS = new Set<FilterOperator>(['isEmpty', 'isNotEmpty']);

/**
 * Names the server accepts as an operator (URL form and key).
 */
const OPERATOR_NAMES = Object.entries(FILTER_OPERATOR_URL_NAMES).flatMap(
    ([key, urlName]) => [key.toLowerCase(), urlName],
);

/**
 * `[{ id: 'created_at', desc: true }, { id: 'name', desc: false }]` → `-created_at,name`.
 */
export function serializeSorting(sorting: ServerSort[]): string {
    return sorting
        .map((sort) => (sort.desc ? `-${sort.id}` : sort.id))
        .join(',');
}

/**
 * Value of `filter[<col>]` with the `[<operator>.]<value>` syntax.
 * Returns `null` when the filter has no value (it must not go in the URL).
 */
export function serializeFilter(filter: ServerFilter): string | null {
    const urlName = FILTER_OPERATOR_URL_NAMES[filter.operator];

    if (VALUELESS_OPERATORS.has(filter.operator)) {
        return urlName;
    }

    const raw = LIST_OPERATORS.has(filter.operator)
        ? serializeList(filter)
        : serializeSingle(filter.value);

    if (raw === null) {
        return null;
    }

    const isImplicit = filter.operator === IMPLICIT_OPERATORS[filter.variant];

    return isImplicit && !startsWithOperatorName(raw)
        ? raw
        : `${urlName}.${raw}`;
}

/**
 * Query string `[key, value]` pairs for the given state. Leaves out whatever
 * matches the default so URLs stay clean.
 */
export function stateToQuery(
    state: TableQueryState,
    config: ServerTableConfig,
): Array<[string, string]> {
    const keys = config.query;
    const pairs: Array<[string, string]> = [];

    if (state.pageIndex > 0) {
        pairs.push([keys.page, String(state.pageIndex + 1)]);
    }

    if (state.pageSize !== config.per_page) {
        pairs.push([keys.per_page, String(state.pageSize)]);
    }

    if (state.sorting.length > 0) {
        pairs.push([keys.sort, serializeSorting(state.sorting)]);
    }

    pairs.push(...filterPairs(state.filters, keys.filter));

    const search = state.globalFilter.trim();

    if (search !== '') {
        pairs.push([keys.search, search]);
    }

    const visible = visibleColumns(state.columnVisibility, config.columns);
    const defaults = config.columns
        .filter((column) => column.visible)
        .map((column) => column.id);

    if (visible.join(',') !== defaults.join(',')) {
        pairs.push([keys.columns, visible.join(',')]);
    }

    return pairs;
}

/**
 * URL with the table state, keeping the parameters that are not its own
 * (other tables on the page, the screen's own filters…).
 */
export function buildTableUrl(
    href: string,
    pairs: Array<[string, string]>,
    keys: ServerQueryKeys,
): string {
    const url = new URL(href);
    const kept = [...url.searchParams.entries()].filter(
        ([key]) => !isTableQueryKey(key, keys),
    );
    const query = [...kept, ...pairs]
        .map(([key, value]) => `${encodeKey(key)}=${encodeValue(value)}`)
        .join('&');

    return `${url.pathname}${query === '' ? '' : `?${query}`}${url.hash}`;
}

export interface ArrangeColumnsOptions<T> {
    /** Id of the client column, if it has one. */
    getId: (column: T) => string | undefined;
    /** Client-only columns that go first (e.g. the selection column). */
    isLeading: (column: T) => boolean;
    /** Final column for a server id; receives the client one if it exists. */
    resolve: (id: string, column: T | undefined) => T;
}

/**
 * The table class decides which columns exist and in which order: every server
 * column appears in its order, using the client column with the same id if it
 * exists. Client-only columns go at the end, except the ones marked as leading.
 */
export function arrangeColumns<T>(
    clientColumns: readonly T[],
    serverIds: readonly string[],
    { getId, isLeading, resolve }: ArrangeColumnsOptions<T>,
): T[] {
    const server = new Set(serverIds);
    const byId = new Map<string, T>();
    const leading: T[] = [];
    const trailing: T[] = [];

    for (const column of clientColumns) {
        const id = getId(column);

        if (id !== undefined && server.has(id)) {
            byId.set(id, column);
        } else if (isLeading(column)) {
            leading.push(column);
        } else {
            trailing.push(column);
        }
    }

    return [
        ...leading,
        ...serverIds.map((id) => resolve(id, byId.get(id))),
        ...trailing,
    ];
}

export function isTableQueryKey(key: string, keys: ServerQueryKeys): boolean {
    return (
        key === keys.page ||
        key === keys.per_page ||
        key === keys.sort ||
        key === keys.search ||
        key === keys.columns ||
        key === keys.filter ||
        key.startsWith(`${keys.filter}[`)
    );
}

function filterPairs(
    filters: ServerFilter[],
    filterKey: string,
): Array<[string, string]> {
    const byColumn = new Map<string, string[]>();

    for (const filter of filters) {
        const value = serializeFilter(filter);

        if (value === null) {
            continue;
        }

        byColumn.set(filter.id, [...(byColumn.get(filter.id) ?? []), value]);
    }

    return [...byColumn.entries()].flatMap(([id, values]) =>
        values.length === 1
            ? [[`${filterKey}[${id}]`, values[0] ?? ''] as [string, string]]
            : values.map(
                  (value) =>
                      [`${filterKey}[${id}][]`, value] as [string, string],
              ),
    );
}

function visibleColumns(
    visibility: Record<string, boolean>,
    columns: ServerColumnConfig[],
): string[] {
    return columns
        .filter(
            (column) =>
                !column.hideable || (visibility[column.id] ?? column.visible),
        )
        .map((column) => column.id);
}

function serializeList(filter: ServerFilter): string | null {
    const values = Array.isArray(filter.value) ? filter.value : [filter.value];

    if (filter.operator === 'isBetween') {
        const [from = '', to = ''] = values;

        return from === '' && to === '' ? null : joinList([from, to]);
    }

    const present = values.filter((value) => value !== '');

    return present.length === 0 ? null : joinList(present);
}

function serializeSingle(value: string | string[]): string | null {
    const single = Array.isArray(value) ? (value[0] ?? '') : value;

    return single.trim() === '' ? null : single;
}

/**
 * Comma-separated list; values with commas, quotes or surrounding spaces are
 * quoted, doubling the inner quotes.
 */
function joinList(values: string[]): string {
    return values
        .map((value) =>
            /[,"]/.test(value) || value !== value.trim()
                ? `"${value.replaceAll('"', '""')}"`
                : value,
        )
        .join(',');
}

function startsWithOperatorName(raw: string): boolean {
    const lower = raw.toLowerCase();

    return OPERATOR_NAMES.some(
        (name) => lower === name || lower.startsWith(`${name}.`),
    );
}

/**
 * Brackets and commas are kept readable: they are valid in a query string.
 */
function encodeKey(key: string): string {
    return encodeURIComponent(key)
        .replaceAll('%5B', '[')
        .replaceAll('%5D', ']');
}

function encodeValue(value: string): string {
    return encodeURIComponent(value).replaceAll('%2C', ',');
}

/**
 * The only file of `lib/` that knows the UI framework: the `lib/data-table-*`
 * files import TanStack Table and the framework types from here, so React and
 * Vue share them and each one installs its own copy of this file.
 */
import type { Component, CSSProperties } from 'vue';

import type { TableFeature } from '@tanstack/vue-table';

import type { ColumnFilterItem } from '@/lib/data-table-types';

export * from '@tanstack/vue-table';

/** An icon component: `meta.icon`, `meta.icons` and the options' `icon`. */
export type DataTableIcon = Component;

/** Inline styles of a header or a cell (the column size). */
export type DataTableStyle = CSSProperties;

declare module '@tanstack/vue-table' {
    interface Plugins {
        dataTableFilteringFeature: TableFeature;
    }

    interface ColumnFilter extends Partial<
        Pick<ColumnFilterItem, 'operator' | 'variant' | 'filterId'>
    > {}
}

// Copyright (c) 2024 Sadman Sakib. SPDX-License-Identifier: MIT

import {
    assignPrototypeAPIs,
    assignTableAPIs,
    type Column,
    type ColumnFilter,
    columnFilteringFeature,
    columnOrderingFeature,
    columnPinningFeature,
    columnSizingFeature,
    columnVisibilityFeature,
    functionalUpdate,
    metaHelper,
    type RowData,
    rowPaginationFeature,
    rowSelectionFeature,
    rowSortingFeature,
    setStateSlice,
    type Table,
    type TableFeature,
    tableFeatures,
    type Updater,
    globalFilteringFeature,
} from '@/lib/data-table-tanstack';

import type {
    DataTableColumnMeta,
    DataTableTableMeta,
} from '@/lib/data-table-types';

import {
    getIsPlainFilter,
    getPlainFilterValue,
    normalizeColumnFilter,
} from '@/lib/data-table-filter-values';

type DataTableInstance = Table<DataTableFeatures, RowData>;

/**
 * The table filters on the server (`manualFiltering`): this feature only keeps
 * its filters in the URL format. A column has one "plain" filter, the value its
 * filter component edits (`column.getFilterValue()`), and, with `empty: true`
 * in PHP, an `is.empty` filter next to it for the rows without a value.
 */
const dataTableFilteringFeature: TableFeature = {
    getDefaultColumnDef: () => ({
        enableColumnFilter: false,
    }),
    assignColumnPrototype: (prototype, table) => {
        const instance = asDataTable(table);

        assignPrototypeAPIs('dataTableFilteringFeature', prototype, table, {
            column_getFilterValue: {
                fn: (column: { id: string }) =>
                    getPlainFilter(
                        instance,
                        column.id,
                        instance.atoms.columnFilters.get(),
                    ).value,
                memoDeps: () => [instance.atoms.columnFilters.get()],
            },
            column_setFilterValue: {
                fn: (column: { id: string }, updater: Updater<unknown>) =>
                    setPlainFilter(instance, column.id, updater),
            },
        });
    },
    constructTableAPIs: (table) => {
        assignTableAPIs('dataTableFilteringFeature', table, {
            table_setColumnFilters: {
                fn: (updater: Updater<ColumnFilter[]>) =>
                    setStateSlice(
                        table,
                        'columnFilters',
                        (old: ColumnFilter[]) =>
                            functionalUpdate(updater, old).filter(
                                (filter) => !getShouldRemoveFilter(filter),
                            ),
                    ),
            },
        });
    },
};

/**
 * Feature hooks get a `Table` generic over any features. This feature is only
 * registered in `dataTableFeatures`, so its hooks can use that table's types.
 */
function asDataTable(table: object) {
    return table as DataTableInstance;
}

function getPlainFilter(
    instance: DataTableInstance,
    columnId: string,
    filters: ColumnFilter[],
) {
    const variant =
        instance.getColumn(columnId)?.columnDef.meta?.filterVariant ?? 'text';
    const index = filters.findIndex(
        (filter) =>
            filter.id === columnId &&
            getIsPlainFilter(normalizeColumnFilter(filter, variant)),
    );
    const filter = filters[index];
    const value = filter
        ? getPlainFilterValue(normalizeColumnFilter(filter, variant))
        : undefined;

    return { index, filter, value };
}

function setPlainFilter(
    instance: DataTableInstance,
    columnId: string,
    updater: Updater<unknown>,
) {
    instance.setColumnFilters((old) => {
        const {
            index,
            filter: previous,
            value: previousValue,
        } = getPlainFilter(instance, columnId, old);
        const value = functionalUpdate(updater, previousValue);
        const next: ColumnFilter = previous?.filterId
            ? { id: columnId, value, filterId: previous.filterId }
            : { id: columnId, value };

        if (index === -1) return [...old, next];
        return old.map((filter, filterIndex) =>
            filterIndex === index ? next : filter,
        );
    });
}

/**
 * Only an `undefined` value removes a filter: a cleared filter that keeps an
 * empty value (`''`, `[]`) is sent as no filter, and the `is.empty` filter,
 * whose value is `''`, must survive TanStack's default removal of empty text.
 */
function getShouldRemoveFilter(filter: ColumnFilter) {
    return filter.value === undefined;
}

export const dataTableFeatures = tableFeatures({
    columnFilteringFeature,
    globalFilteringFeature,
    columnOrderingFeature,
    columnPinningFeature,
    columnSizingFeature,
    columnVisibilityFeature,
    rowPaginationFeature,
    rowSelectionFeature,
    rowSortingFeature,
    dataTableFilteringFeature,
    columnMeta: metaHelper<DataTableColumnMeta>(),
    tableMeta: metaHelper<DataTableTableMeta>(),
});

export type DataTableFeatures = typeof dataTableFeatures;

type DataTableColumn<TData extends RowData, TValue> = Column<
    DataTableFeatures,
    TData,
    TValue
>;

function isEmptyFilterOf(filter: ColumnFilter, columnId: string) {
    return filter.id === columnId && filter.operator === 'isEmpty';
}

/**
 * Whether the filter of the column also takes the rows without a value: an
 * `is.empty` filter next to its plain one, added with OR by the server
 * (`empty: true` in PHP).
 */
export function getEmptyFilter<TData extends RowData, TValue>(
    column: DataTableColumn<TData, TValue>,
): boolean {
    return column.table.atoms.columnFilters
        .get()
        .some((filter) => isEmptyFilterOf(filter, column.id));
}

/** Adds or removes the rows without a value, keeping the picked values. */
export function setEmptyFilter<TData extends RowData, TValue>(
    column: DataTableColumn<TData, TValue>,
    include: boolean,
) {
    const variant = column.columnDef.meta?.filterVariant ?? 'text';

    column.table.setColumnFilters((old) => {
        const rest = old.filter(
            (filter) => !isEmptyFilterOf(filter, column.id),
        );

        return include && variant
            ? [
                  ...rest,
                  {
                      id: column.id,
                      value: '',
                      variant,
                      operator: 'isEmpty',
                      filterId: `${column.id}-empty`,
                  },
              ]
            : rest;
    });
}

/** Removes every filter of the column, the rows without a value included. */
export function clearColumnFilter<TData extends RowData, TValue>(
    column: DataTableColumn<TData, TValue>,
) {
    column.table.setColumnFilters((old) =>
        old.filter((filter) => filter.id !== column.id),
    );
}

// Copyright (c) 2024 Sadman Sakib. SPDX-License-Identifier: MIT

import {
    DEFAULT_MESSAGES,
    getMessage,
    type TableWithMeta,
} from '@/lib/data-table-messages';
import type {
    ColumnDisplay,
    ColumnSelectOption,
    CurrencyDisplay,
    DataTableColumnMeta,
    DatePreset,
} from '@/lib/data-table-types';

export function formatDate(
    date: Date | string | number | undefined,
    opts: Intl.DateTimeFormatOptions = {},
    locale?: string,
) {
    if (!date) return '';

    try {
        return new Intl.DateTimeFormat(locale, {
            month: opts.month ?? 'long',
            day: opts.day ?? 'numeric',
            year: opts.year ?? 'numeric',
            ...opts,
        }).format(new Date(date));
    } catch {
        return '';
    }
}

const DATE_PRESETS: Record<
    Exclude<DatePreset, 'relative'>,
    Intl.DateTimeFormatOptions
> = {
    short: { dateStyle: 'short' },
    medium: { dateStyle: 'medium' },
    long: { dateStyle: 'long' },
    datetime: { dateStyle: 'medium', timeStyle: 'short' },
};

const RELATIVE_UNITS: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ['year', 31_536_000],
    ['month', 2_592_000],
    ['week', 604_800],
    ['day', 86_400],
    ['hour', 3_600],
    ['minute', 60],
    ['second', 1],
];

/**
 * Number with Intl options (`{ style: 'currency', currency: 'CLP' }`…). Texts
 * that are not numbers are returned as they are. Currencies follow `currency`:
 * the symbol before the number (`$1.234`, in any locale), the code after it
 * (`1.234 CLP`), both (`$1.234 CLP`) or nothing (`1.234`); the locale gives the
 * separators.
 */
export function formatNumber(
    value: unknown,
    format: Intl.NumberFormatOptions = {},
    locale?: string,
    currency: CurrencyDisplay = 'symbol',
): string {
    const number = toNumber(value);

    if (number === null) {
        return toText(value);
    }

    try {
        if (
            format.style === 'currency' &&
            format.currencyDisplay === undefined
        ) {
            return formatMoney(number, format, locale, currency);
        }

        return new Intl.NumberFormat(locale, format).format(number);
    } catch {
        return String(number);
    }
}

function formatMoney(
    number: number,
    format: Intl.NumberFormatOptions,
    locale: string | undefined,
    currency: CurrencyDisplay,
): string {
    const parts = new Intl.NumberFormat(locale, {
        ...format,
        currencyDisplay: 'narrowSymbol',
    }).formatToParts(number);
    const symbol = parts.find((part) => part.type === 'currency')?.value ?? '';
    const sign = parts.find((part) => part.type === 'minusSign')?.value ?? '';
    const digits = parts
        .filter(
            (part) =>
                part.type !== 'currency' &&
                part.type !== 'minusSign' &&
                !(part.type === 'literal' && part.value.trim() === ''),
        )
        .map((part) => part.value)
        .join('');

    const code = format.currency?.toUpperCase() ?? '';

    switch (currency) {
        case 'code':
            return `${sign}${digits} ${code}`.trim();
        case 'both':
            return `${sign}${symbol}${digits} ${code}`.trim();
        case 'none':
            return `${sign}${digits}`;
        default:
            return `${sign}${symbol}${digits}`;
    }
}

export interface NumberCellParts {
    text: string;
    suffix?: string;
}

/**
 * Number cell split in the number and what goes after it, which the cell shows
 * smaller and muted: the currency code with `cell: 'code'` or `'both'` or the
 * unit of plain numbers (`->unit('kg')`). Without one, `text` is the whole
 * formatted value.
 */
export function formatNumberCell(
    meta: DataTableColumnMeta | undefined,
    value: unknown,
    locale?: string,
): NumberCellParts {
    const display = meta?.display?.type === 'number' ? meta.display : undefined;
    const format = display?.format;
    const cell = display?.currency?.cell;
    let suffix: string | undefined;

    if (toNumber(value) !== null) {
        if (format?.style === 'currency') {
            suffix =
                format.currencyDisplay === undefined &&
                (cell === 'code' || cell === 'both')
                    ? format.currency?.toUpperCase()
                    : undefined;
        } else if (format?.style === undefined) {
            suffix = getUnit(meta);
        }
    }

    if (!suffix) {
        return { text: formatCellValue(meta, value, locale) };
    }

    return {
        text: formatNumber(
            value,
            format,
            locale,
            cell === 'both' ? 'symbol' : 'none',
        ),
        suffix,
    };
}

export interface FilterAffix {
    text: string;
    align: 'inline-start' | 'inline-end';
}

/** Undefined with a currency Intl does not know: the filter shows no symbol. */
function getCurrencySymbol(
    format: Intl.NumberFormatOptions,
): string | undefined {
    try {
        return new Intl.NumberFormat(undefined, {
            ...format,
            currencyDisplay: 'narrowSymbol',
        })
            .formatToParts(0)
            .find((part) => part.type === 'currency')?.value;
    } catch {
        return undefined;
    }
}

/**
 * What goes next to the number inputs of a filter, which take the raw value:
 * the unit of plain numbers (`->unit('kg')`) after them or, for `->money()`,
 * the symbol before (`$`, by default), the code after (`CLP`) or both, as
 * chosen with `filter:`. Percentages and Intl units have none.
 */
export function getFilterAffixes(
    meta: DataTableColumnMeta | undefined,
): FilterAffix[] {
    const display = meta?.display?.type === 'number' ? meta.display : undefined;
    const format = display?.format;

    if (format?.style === 'currency' && format.currency) {
        const shown = display?.currency?.filter ?? 'symbol';
        const affixes: FilterAffix[] = [];

        if (shown === 'symbol' || shown === 'both') {
            const symbol = getCurrencySymbol(format);

            if (symbol) {
                affixes.push({ text: symbol, align: 'inline-start' });
            }
        }

        if (shown === 'code' || shown === 'both') {
            affixes.push({
                text: format.currency.toUpperCase(),
                align: 'inline-end',
            });
        }

        return affixes;
    }

    const unit =
        format?.style === undefined ? getUnit(meta, 'filter') : undefined;

    return unit ? [{ text: unit, align: 'inline-end' }] : [];
}

/**
 * Date with a preset or Intl options. Dates without time (`2026-01-15`, or
 * midnight UTC as Laravel serializes `date` casts) are formatted in UTC so they
 * do not move to the previous day west of Greenwich.
 */
export function formatDateValue(
    value: unknown,
    format: ColumnDisplayDateFormat = 'long',
    locale?: string,
    now: Date = new Date(),
): string {
    const parsed = parseDate(value);

    if (parsed === null) {
        return toText(value);
    }

    if (format === 'relative') {
        return formatRelativeDate(parsed, now, locale);
    }

    const options = getDateOptions(
        typeof format === 'string' ? DATE_PRESETS[format] : format,
        parsed.dateOnly,
    );

    try {
        return new Intl.DateTimeFormat(locale, options).format(parsed.date);
    } catch {
        return toText(value);
    }
}

const TIME_OPTIONS = ['timeStyle', 'hour', 'minute', 'second'] as const;
const TIME_ONLY_OPTIONS = [
    'fractionalSecondDigits',
    'dayPeriod',
    'hour12',
    'hourCycle',
    'timeZoneName',
] as const;

/**
 * A date without time has no hour to show and no time zone to move it: its
 * time parts are left out and it is formatted in UTC, also with a format that
 * has time (`datetime`), which would show the evening of the day before.
 */
function getDateOptions(
    options: Intl.DateTimeFormatOptions,
    dateOnly: boolean,
): Intl.DateTimeFormatOptions {
    if (!dateOnly || options.timeZone !== undefined) {
        return options;
    }

    const date: Intl.DateTimeFormatOptions = { ...options };
    const hadTime = TIME_OPTIONS.some((key) => options[key] !== undefined);

    for (const key of [...TIME_OPTIONS, ...TIME_ONLY_OPTIONS]) {
        delete date[key];
    }

    return {
        // Only a time was asked for: the date is all there is to show.
        ...(hadTime && Object.keys(date).length === 0
            ? { dateStyle: 'medium' as const }
            : date),
        timeZone: 'UTC',
    };
}

type ColumnDisplayDateFormat = Extract<
    ColumnDisplay,
    { type: 'date' }
>['format'];

function formatRelativeDate(
    { date, dateOnly }: ParsedDate,
    now: Date,
    locale?: string,
): string {
    const formatter = createRelativeTimeFormat(locale);
    // A date without time is compared by days: "yesterday", not "in 21 hours".
    const seconds = dateOnly
        ? (date.getTime() -
              Date.UTC(now.getFullYear(), now.getMonth(), now.getDate())) /
          1000
        : (date.getTime() - now.getTime()) / 1000;
    const units = dateOnly
        ? RELATIVE_UNITS.filter(([, size]) => size >= 86_400)
        : RELATIVE_UNITS;
    const [unit, size] = units.find(([, size]) => Math.abs(seconds) >= size) ??
        units[units.length - 1] ?? ['second', 1];

    return formatter.format(Math.round(seconds / size), unit);
}

/** An unknown locale falls back to the browser's, like the other formats. */
function createRelativeTimeFormat(locale?: string): Intl.RelativeTimeFormat {
    try {
        return new Intl.RelativeTimeFormat(locale, { numeric: 'auto' });
    } catch {
        return new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' });
    }
}

/**
 * A date without time: `2026-01-15` or midnight UTC (Laravel `date` casts).
 */
export function isDateOnly(value: unknown): boolean {
    return parseDate(value)?.dateOnly ?? false;
}

interface ParsedDate {
    date: Date;
    dateOnly: boolean;
}

function parseDate(value: unknown): ParsedDate | null {
    if (value instanceof Date) {
        return Number.isNaN(value.getTime())
            ? null
            : { date: value, dateOnly: false };
    }

    if (typeof value === 'number') {
        const date = new Date(value);

        // Beyond ±8.64e15 ms there is no valid date: show the raw value instead.
        return Number.isNaN(date.getTime()) ? null : { date, dateOnly: false };
    }

    if (typeof value !== 'string' || value.trim() === '') {
        return null;
    }

    const dateOnly =
        /^\d{4}-\d{2}-\d{2}$/.test(value) ||
        /T00:00:00(\.0+)?(Z|[+-]00:?00)$/.test(value);
    const date = new Date(
        /^\d{4}-\d{2}-\d{2}$/.test(value) ? `${value}T00:00:00Z` : value,
    );

    return Number.isNaN(date.getTime()) ? null : { date, dateOnly };
}

/**
 * Cuts a text to `limit` characters (not code units), adding an ellipsis.
 */
export function truncate(text: string, limit?: number): string {
    const characters = Array.from(text);

    return limit === undefined || characters.length <= limit
        ? text
        : `${characters.slice(0, limit).join('').trimEnd()}…`;
}

/**
 * Only http and https URLs become links (never `javascript:`).
 */
export function isSafeUrl(url: string): boolean {
    try {
        const { protocol } = new URL(url);

        return protocol === 'http:' || protocol === 'https:';
    } catch {
        return false;
    }
}

export function isEmail(value: string): boolean {
    return /^[^\s@]+@[^\s@]+$/.test(value);
}

/**
 * Defaults of the table to format a cell: `getFormatContext(table)`.
 */
export interface FormatContext {
    locale?: string;
    /** Format of the dates without `display`; `long` by default. */
    dateFormat?: DatePreset;
    /** Texts of true and false without `display.labels`; Yes / No by default. */
    booleanLabels?: { true: string; false: string };
}

/**
 * Locale, date format and Yes / No texts of the table (`table.options.meta`).
 */
export function getFormatContext(
    table: TableWithMeta | undefined,
): FormatContext {
    const meta = table?.options.meta;

    return {
        locale: meta?.locale,
        dateFormat: meta?.dateFormat,
        booleanLabels: {
            true: getMessage(table, 'yes'),
            false: getMessage(table, 'no'),
        },
    };
}

/**
 * Text of a cell as the default cell shows it: the column `display` (format
 * declared in PHP or in the page `meta`) or, without it, the filter variant.
 * The third argument is the locale or the defaults of the table.
 */
export function formatCellValue(
    meta: DataTableColumnMeta | undefined,
    value: unknown,
    context: string | FormatContext = {},
): string {
    if (value === null || value === undefined || value === '') {
        return '';
    }

    const {
        locale,
        dateFormat = 'long',
        booleanLabels,
    } = typeof context === 'string' ? { locale: context } : context;

    if (Array.isArray(value)) {
        return value
            .map((item) => formatCellValue(meta, item, context))
            .join(', ');
    }

    const display = meta?.display;

    switch (display?.type) {
        case 'number':
            return withUnit(
                formatNumber(
                    value,
                    display.format,
                    locale,
                    display.currency?.cell,
                ),
                meta,
                display.format,
            );
        case 'date':
            return formatDateValue(value, display.format ?? dateFormat, locale);
        case 'text':
            return truncate(toText(value), display.limit);
        case 'boolean':
            return formatBoolean(value, display.labels ?? booleanLabels);
        case 'option':
            return getOptionLabel(meta, toPrimitive(value));
    }

    if (typeof value === 'boolean') {
        return formatBoolean(value, booleanLabels);
    }

    return toText(value);
}

/**
 * Some databases (SQLite, MySQL) return 1/0 instead of true/false.
 */
export function formatBoolean(
    value: unknown,
    labels: { true: string; false: string } = {
        true: DEFAULT_MESSAGES.yes,
        false: DEFAULT_MESSAGES.no,
    },
): string {
    return value === true || value === 1 || value === '1' || value === 'true'
        ? labels.true
        : labels.false;
}

/**
 * Label of an option (select / multi-select) as declared by the server, to
 * show `Administrator` instead of `admin` in a cell.
 */
export function getOptionLabel(
    meta: DataTableColumnMeta | undefined,
    value: string | number | boolean | null | undefined,
): string {
    const text = value === null || value === undefined ? '' : String(value);

    return getOption(meta, value)?.label ?? text;
}

/**
 * Own entry of a record keyed by a server value. A plain object lookup would
 * return inherited members for values like `constructor` or `__proto__`.
 */
export function getOwn<T>(
    record: Record<string, T> | undefined,
    key: string,
): T | undefined {
    return record && Object.hasOwn(record, key) ? record[key] : undefined;
}

/**
 * Option (select / multi-select) of a value, with its label, count and the
 * icon declared in the page `meta` (`meta.icons` or `meta.options`).
 */
export function getOption(
    meta: DataTableColumnMeta | undefined,
    value: string | number | boolean | null | undefined,
): ColumnSelectOption | undefined {
    const text = value === null || value === undefined ? '' : String(value);
    const option = meta?.options?.find((item) => item.value === text);
    const icon = getOwn(meta?.icons, text);

    return icon && !option?.icon
        ? { value: text, label: text, ...option, icon }
        : option;
}

/**
 * Whether a cell has nothing to show: `null`, `undefined`, `''` or a list of
 * those.
 */
export function isEmptyValue(value: unknown): boolean {
    if (Array.isArray(value)) {
        return value.every(isEmptyValue);
    }

    return value === null || value === undefined || value === '';
}

/**
 * Name of the rows without a value in the filters: the text of
 * `->whenEmpty()` or the `no_value` text of the UI.
 */
export function getEmptyLabel(
    meta: DataTableColumnMeta | undefined,
    table?: TableWithMeta,
): string {
    const empty = meta?.display?.empty;

    // A placeholder like "—" or "-" says nothing as a filter label.
    return empty && /[\p{L}\p{N}]/u.test(empty)
        ? empty
        : getMessage(table, 'no_value');
}

export function toText(value: unknown): string {
    switch (typeof value) {
        case 'string':
            return value;
        case 'number':
        case 'bigint':
        case 'boolean':
            return String(value);
        case 'object':
            return value === null ? '' : JSON.stringify(value);
        default:
            return '';
    }
}

export function toPrimitive(value: unknown): string | number | boolean | null {
    return typeof value === 'string' ||
        typeof value === 'number' ||
        typeof value === 'boolean'
        ? value
        : null;
}

function toNumber(value: unknown): number | null {
    if (typeof value === 'number') {
        return Number.isFinite(value) ? value : null;
    }

    if (typeof value === 'string' && value.trim() !== '') {
        const number = Number(value);

        return Number.isFinite(number) ? number : null;
    }

    return null;
}

/**
 * Unit of the column in the cells (and the filter label) or next to the filter
 * inputs: `->unit('kg', cell: false)` in PHP or `display.unit` in the page.
 */
export function getUnit(
    meta: DataTableColumnMeta | undefined,
    place: 'cell' | 'filter' = 'cell',
): string | undefined {
    const display = meta?.display?.type === 'number' ? meta.display : undefined;

    return display?.showUnit?.[place] === false ? undefined : display?.unit;
}

/**
 * The unit goes after plain numbers, not after currencies, percentages or
 * Intl units.
 */
function withUnit(
    text: string,
    meta: DataTableColumnMeta | undefined,
    format?: Intl.NumberFormatOptions,
): string {
    const unit = getUnit(meta);

    return unit && format?.style === undefined ? `${text} ${unit}` : text;
}

import type { DataTableTableMeta } from '@/lib/data-table-types';

/**
 * Texts of the UI in English: the same keys as `lang/en/ui.php` of the
 * package. The server sends them translated to the app language in
 * `config.messages`, and `useServerDataTable({ messages })` changes any of them.
 */
export const DEFAULT_MESSAGES = {
    search: 'Search...',
    reset: 'Reset',
    reset_filters: 'Reset filters',
    view: 'View',
    view_columns: 'View columns',
    columns: 'Columns',
    search_columns: 'Search columns...',
    no_columns: 'No columns found.',

    no_results: 'No results.',
    loading: 'Loading table…',
    load_error: 'The table could not be loaded.',
    retry: 'Retry',
    yes: 'Yes',
    no: 'No',
    empty: '—',
    no_value: 'No value',

    sort_ascending: 'Asc',
    sort_descending: 'Desc',
    hide: 'Hide',
    column_menu: ':label column options',

    filter: ':label filter',
    clear: 'Clear',
    clear_filter: 'Clear :label filter',
    clear_filters: 'Clear filters',
    no_options: 'No results found.',
    selected: ':count selected',
    from: 'From',
    to: 'to',
    slider: ':label slider',
    previous_month: 'Go to the previous month',
    next_month: 'Go to the next month',

    rows_per_page: 'Rows per page',
    page_of: 'Page :page of :pages',
    row_selected: ':count row selected.',
    rows_selected: ':count rows selected.',
    not_shown: '(:count not shown)',
    first_page: 'Go to first page',
    previous_page: 'Go to previous page',
    next_page: 'Go to next page',
    last_page: 'Go to last page',
};

export type DataTableMessageKey = keyof typeof DEFAULT_MESSAGES;

export type DataTableMessages = Record<DataTableMessageKey, string>;

type Replacements = Record<string, string | number>;

export interface TableWithMeta {
    options: { meta?: DataTableTableMeta };
}

/**
 * Text of the UI with its placeholders replaced: `getMessage(table, 'filter',
 * { label: 'Status' })` → `Status filter`. Without a text for the key, the
 * English one.
 */
export function getMessage(
    table: TableWithMeta | undefined,
    key: DataTableMessageKey,
    replacements: Replacements = {},
): string {
    return replacePlaceholders(
        table?.options.meta?.messages?.[key] ?? DEFAULT_MESSAGES[key],
        replacements,
    );
}

/**
 * Replaces `:name` with its value, longest names first so that `:page` does not
 * eat the start of `:pages`.
 */
export function replacePlaceholders(
    text: string,
    replacements: Replacements,
): string {
    const names = Object.keys(replacements).sort((a, b) => b.length - a.length);

    if (names.length === 0) {
        return text;
    }

    // One pass and a function: a value is neither read as a pattern (`$&`)
    // nor replaced again when it holds another placeholder.
    return text.replace(
        new RegExp(`:(${names.map(escapeRegExp).join('|')})`, 'g'),
        (_, name: string) => String(replacements[name]),
    );
}

/**
 * Texts of the table: the English ones, those of the server and those of the
 * page, in that order; unknown keys and empty values are ignored.
 */
export function mergeMessages(
    ...sources: Array<Partial<Record<string, string>> | null | undefined>
): DataTableMessages {
    const messages: DataTableMessages = { ...DEFAULT_MESSAGES };

    for (const source of sources) {
        for (const [key, value] of Object.entries(source ?? {})) {
            if (key in DEFAULT_MESSAGES && typeof value === 'string') {
                messages[key as DataTableMessageKey] = value;
            }
        }
    }

    return messages;
}

// Regions whose week starts on Sunday (CLDR); the rest, on Monday, except
// the ones of SATURDAY_REGIONS.
const SUNDAY_REGIONS = new Set(
    'AG AS BD BR BS BT BW BZ CA CN CO DM DO ET GT GU HK HN ID IL IN JM JP KE KH KR LA MH MM MO MT MX MZ NI NP PA PE PH PK PR PT PY SA SG SV TH TT TW UM US VE VI WS YE ZA ZW'.split(
        ' ',
    ),
);
const SATURDAY_REGIONS = new Set(
    'AE AF BH DJ DZ EG IQ IR JO KW LY OM QA SD SY'.split(' '),
);

type WeekDay = 0 | 1 | 2 | 3 | 4 | 5 | 6;

interface LocaleWithWeekInfo extends Intl.Locale {
    getWeekInfo?: () => { firstDay: number };
    weekInfo?: { firstDay: number };
}

/**
 * First day of the week of a locale (0 = Sunday), for the calendar: Monday in
 * `es-CL`, Sunday in `en-US`. Without a locale, the browser's.
 */
export function getWeekStartsOn(locale?: string): WeekDay {
    try {
        const resolved = new Intl.Locale(
            locale ?? new Intl.DateTimeFormat().resolvedOptions().locale,
        ) as LocaleWithWeekInfo;
        const firstDay =
            resolved.getWeekInfo?.().firstDay ?? resolved.weekInfo?.firstDay;

        if (firstDay !== undefined) {
            return (firstDay % 7) as WeekDay;
        }

        const region = resolved.maximize().region ?? '';

        if (SUNDAY_REGIONS.has(region)) {
            return 0;
        }

        return SATURDAY_REGIONS.has(region) ? 6 : 1;
    } catch {
        return 0;
    }
}

function escapeRegExp(text: string): string {
    return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

